const trig = $input.item.json;
const DEFAULT_EVENT_NAME = 'Pipeline After the Webinar: Turning Event Engagement into Revenue';

const eventName = (trig.event_name && String(trig.event_name).trim()) || DEFAULT_EVENT_NAME;
const live = trig.live === true || trig.live === 'true';

const base = { event_name: eventName, live };

const reg = trig.registrants_csv;
if (typeof reg === 'string' && reg.trim().length > 0) {
  base.registrants_csv = reg;
}
const transcript = trig.transcript_md;
if (typeof transcript === 'string' && transcript.trim().length > 0) {
  base.transcript_md = transcript;
}

return [{
  json: {
    event_name: eventName,
    live,
    base_request: base,
    has_custom_registrants: !!base.registrants_csv,
    has_custom_transcript: !!base.transcript_md,
  }
}];

const item = $input.item.json;
const slug = String(item.event_name || 'unknown-event')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/(^-|-$)/g, '');
const dateStr = new Date().toISOString().slice(0, 10);
const runKey = `${slug}__${dateStr}`;

return [{
  json: {
    ...item,
    run_key: runKey,
  }
}];

const raw = $input.item.json;
const NODE_TO_MODULE = {
  'M1 — Enrichment': 'm1',
  'M2 — Comms': 'm2',
  'M3 — Repurpose': 'm3',
  'M4 — Dashboard': 'm4',
};
const failedModule = NODE_TO_MODULE[$prevNode.name] || $prevNode.name;
const errMsg = (typeof raw.error === 'string')
  ? raw.error
  : (raw.error && raw.error.message) || raw.message || JSON.stringify(raw).slice(0, 300);

return [{
  json: {
    ok: false,
    module: failedModule,
    error: errMsg,
    hint: 'HTTP-level failure calling POST https://postevent-engine.vercel.app/api/run for module=' + failedModule
      + ' (network error, timeout, or non-2xx). retryOnFail already retried before this fired.',
    log: [],
    run_key: $('Derive Run Key').item.json.run_key,
    event_name: $('Derive Run Key').item.json.event_name,
  }
}];

const m1 = $('M1 — Enrichment').item.json;
const m2 = $('M2 — Comms').item.json;
const m3 = $('M3 — Repurpose').item.json;
const m4 = $json;

const modules = { m1, m2, m3, m4 };
const failures = Object.entries(modules)
  .filter(([, r]) => r && r.ok === false)
  .map(([name, r]) => ({ module: name, error: r.error, hint: r.hint }));
const overallOk = failures.length === 0;

const runKey = $('Derive Run Key').item.json.run_key;
const eventName = $('Derive Run Key').item.json.event_name;
const engineLiveAvailable = $('Health Check — GET /api/run').item.json.live_available;

return [{
  json: {
    ok: overallOk,
    run_key: runKey,
    event_name: eventName,
    lane: "cloud-demo (no credentials -- every external call went to the engine's own public API)",
    engine_live_available: engineLiveAvailable,
    modules,
    failures,
    idempotency_note: 'run_key is deterministic per event_name+date. A production instance would check it against a store (DB row / n8n Data table / HubSpot custom object) before letting any write-side node fire twice for the same key. This demo lane performs no writes, so there is nothing to dedupe here -- see the production lane (master.json) for the real CRM writes this key would guard.',
  }
}];
